// Copies the CMS seed JSON (single source of truth: Tourvex-API/content/defaults/<key>.json) into
// app/content/defaults/<key>.js so the site has an in-repo fallback for when the API is unreachable.
//   npm run content:sync            (reads ../Tourvex-API/content/defaults)
//   CONTENT_DEFAULTS_SRC=/path npm run content:sync
// Run it whenever the API seed files change, and commit the generated files.
import { mkdirSync, readdirSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const source = resolve(process.env.CONTENT_DEFAULTS_SRC || join(here, "..", "..", "Tourvex-API", "content", "defaults"));
const target = resolve(here, "..", "app", "content", "defaults");

const files = readdirSync(source).filter((name) => name.endsWith(".json")).sort();
if (files.length === 0) throw new Error(`No seed files found in ${source}`);

mkdirSync(target, { recursive: true });
for (const name of readdirSync(target)) if (name.endsWith(".js")) rmSync(join(target, name));

const banner = "// GENERATED by scripts/sync-content-defaults.mjs from Tourvex-API/content/defaults. Do not edit; run `npm run content:sync`.\n";
const entries = [];
for (const name of files) {
  const key = name.replace(/\.json$/, "");
  const payload = JSON.parse(readFileSync(join(source, name), "utf8"));
  const id = key.replace(/[^a-zA-Z0-9]+(.)?/g, (_, c) => (c ? c.toUpperCase() : ""));
  writeFileSync(join(target, `${key}.js`), `${banner}const ${id} = ${JSON.stringify(payload, null, 2)};\n\nexport default ${id};\n`);
  entries.push({ key, id });
}
const index =
  banner +
  entries.map(({ key, id }) => `import ${id} from "./${key}.js";`).join("\n") +
  "\n\nexport const DEFAULTS = {\n" +
  entries.map(({ key, id }) => `  ${JSON.stringify(key)}: ${id},`).join("\n") +
  "\n};\n";
writeFileSync(join(target, "index.js"), index);
console.log(`Synced ${entries.length} content defaults from ${source}`);
